const body = $input.first().json.body;
const required = ['job_title', 'offer_amount', 'currency'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const offer = parseFloat(body.offer_amount);
if (isNaN(offer) || offer <= 0) return [{ json: { valid: false, error: 'offer_amount must be a positive number' } }];
const scenarios = ['initial_offer', 'counter_received', 'final_round', 'promotion', 'annual_review', 'competing_offer'];
const scenario = scenarios.includes(body.scenario) ? body.scenario : 'initial_offer';
return [{ json: {
  valid: true,
  jobTitle: body.job_title.trim(),
  company: body.company || '',
  industry: body.industry || '',
  location: body.location || '',
  offerAmount: offer,
  offerType: body.offer_type || 'annual_salary',
  currency: body.currency,
  scenario,
  targetAmount: parseFloat(body.target_amount) || null,
  marketDataProvided: (body.market_data || '').slice(0, 500),
  yearsExperience: parseInt(body.years_experience) || null,
  currentSalary: parseFloat(body.current_salary) || null,
  competingOffer: parseFloat(body.competing_offer) || null,
  otherCompensation: (body.other_compensation || '').slice(0, 400),
  specificConcerns: (body.specific_concerns || '').slice(0, 500),
  negotiationStyle: body.negotiation_style || 'collaborative',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const search = $('Research Market Rate').first().json;
const input = $('Validate Input').first().json;
const marketContext = (search.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
return [{ json: { input, marketContext: marketContext || 'No market data found — use general knowledge.' } }];

