Company: {{ $json.input.company || 'not specified' }}
Industry: {{ $json.input.industry || 'not specified' }}
Location: {{ $json.input.location || 'not specified' }}
Scenario: {{ $json.input.scenario.replace(/_/g,' ') }}

Current offer: {{ $json.input.currency }}{{ $json.input.offerAmount }} ({{ $json.input.offerType.replace(/_/g,' ') }})
Target amount: {{ $json.input.targetAmount ? $json.input.currency + $json.input.targetAmount : 'not specified' }}
Current/previous salary: {{ $json.input.currentSalary ? $json.input.currency + $json.input.currentSalary : 'not disclosed' }}
Competing offer: {{ $json.input.competingOffer ? $json.input.currency + $json.input.competingOffer : 'none' }}
Other compensation: {{ $json.input.otherCompensation || 'not specified' }}
Years experience: {{ $json.input.yearsExperience || 'not specified' }}
Negotiation style preference: {{ $json.input.negotiationStyle }}
Specific concerns: {{ $json.input.specificConcerns || 'none' }}
Market data provided: {{ $json.input.marketDataProvided || 'none provided' }}

Market rate research:
{{ $json.marketContext }}

Return this JSON:
{
  "offer_assessment": {
    "verdict": "one of: strong_offer | fair_offer | below_market | significantly_below_market | needs_more_info",
    "market_range_estimate": "estimated range for this role/location/experience based on research",
    "gap_analysis": "how this offer compares to market — be specific with numbers if possible"
  },
  "negotiation_recommendation": {
    "should_negotiate": true,
    "counter_amount": 0,
    "counter_rationale": "why this specific number — what it's based on",
    "confidence": "high | medium | low",
    "best_case": 0,
    "realistic_case": 0,
    "walk_away_point": "at what point to stop negotiating and either accept or decline"
  },
