    {
      "item": "specific compensation element to negotiate if base is stuck",
      "ask": "how to ask for it specifically",
      "value": "rough estimate of value if relevant"
    }
  ],
  "competing_offer_advice": "{{ 'how to use the competing offer tactically — or null if none' if False else 'how to use the competing offer tactically — or null if none' }}",
  "timing_advice": "when and how to have this conversation — timing, channel, follow-up plan",
  "red_flags": ["anything in this situation that suggests unusual risk in negotiating"],
  "one_thing_not_to_do": "the single most common mistake in this specific scenario"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let coaching;
try { coaching = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
coaching._meta = { jobTitle: input.jobTitle, company: input.company, offerAmount: input.offerAmount, currency: input.currency, scenario: input.scenario, replyEmail: input.replyEmail };
return [{ json: coaching }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const cur = m.currency;

const verdictConfig = {
  strong_offer:            {color:'#16a34a', bg:'#f0fdf4', label:'Strong Offer'},
  fair_offer:              {color:'#2563eb', bg:'#eff6ff', label:'Fair Offer'},
  below_market:            {color:'#d97706', bg:'#fffbeb', label:'Below Market'},
  significantly_below_market:{color:'#dc2626', bg:'#fef2f2', label:'Significantly Below Market'},
  needs_more_info:         {color:'#6b7280', bg:'#f9fafb', label:'Needs More Info'}
};
const vc = verdictConfig[c.offer_assessment?.verdict] || verdictConfig.needs_more_info;

const pushbackCards = (c.if_they_push_back||[]).map(p => `
  <div style="border:1px solid #e5e7eb;border-radius:6px;margin-bottom:10px;overflow:hidden">
    <div style="background:#f9fafb;padding:8px 14px;font-size:13px;font-weight:600;color:#374151">They say: "${esc(p.pushback)}"</div>
    <div style="padding:10px 14px;font-size:14px;color:#1e40af;font-style:italic;line-height:1.6">You say: "${esc(p.response)}"</div>
  </div>`).join('');

const beyondBase = (c.beyond_base_salary||[]).map(b => `
  <div style="padding:9px 0;border-bottom:1px solid #f3f4f6">
    <div style="font-size:14px;font-weight:600">${esc(b.item)}</div>
    <div style="font-size:13px;color:#2563eb;margin-top:2px">${esc(b.ask)}</div>
    ${b.value ? `<div style="font-size:12px;color:#9ca3af;margin-top:1px">${esc(b.value)}</div>` : ''}
  </div>`).join('');

const nr = c.negotiation_recommendation;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#1c1917;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#78716c;margin-bottom:5px">Salary Negotiation Coach · ${esc(m.scenario.replace(/_/g,' '))}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.jobTitle)}${m.company ? ' at ' + esc(m.company) : ''}</div>
    <div style="font-size:14px;color:#a8a29e;margin-top:3px">Offer: ${cur}${m.offerAmount.toLocaleString()}</div>
  </div>

  <div style="background:${vc.bg};padding:16px 28px;border:1px solid ${vc.color}44;border-top:none">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px">
      <div>
        <span style="background:${vc.color};color:#fff;font-size:12px;font-weight:700;padding:3px 10px;border-radius:12px">${vc.label}</span>
        <div style="font-size:13px;color:#555;margin-top:6px">${esc(c.offer_assessment?.market_range_estimate)}</div>
      </div>
      ${nr?.should_negotiate && nr?.counter_amount ? `<div style="text-align:right"><div style="font-size:11px;color:#9ca3af;text-transform:uppercase;letter-spacing:0.4px">Counter ask</div><div style="font-size:26px;font-weight:800;color:#1a1a1a">${cur}${nr.counter_amount.toLocaleString()}</div><div style="font-size:12px;color:#6b7280">Realistic: ${cur}${(nr.realistic_case||0).toLocaleString()} · Best case: ${cur}${(nr.best_case||0).toLocaleString()}</div></div>` : ''}
    </div>
    <div style="font-size:13px;color:#555;margin-top:8px;line-height:1.6">${esc(c.offer_assessment?.gap_analysis)}</div>
  </div>

  ${nr ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f3">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:4px">Recommendation · ${esc(nr.confidence)} confidence</div>
    <p style="font-size:14px;line-height:1.65;color:#374151;margin:0 0 10px">${esc(nr.counter_rationale)}</p>
    ${nr.walk_away_point ? `<div style="font-size:13px;color:#dc2626;background:#fef2f2;padding:8px 12px;border-radius:4px">Walk-away: ${esc(nr.walk_away_point)}</div>` : ''}
  </div>` : ''}

  <div style="background:#f0f7ff;padding:18px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:10px">What to say</div>
    <div style="font-size:14px;line-height:1.75;color:#1e3a8a;font-style:italic;white-space:pre-wrap">${esc(c.what_to_say?.opening_script)}</div>
  </div>

  ${c.what_to_say?.email_body ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f3">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:4px">Email draft</div>
    ${c.what_to_say.email_subject ? `<div style="font-size:13px;color:#6b7280;margin-bottom:8px"><strong>Subject:</strong> ${esc(c.what_to_say.email_subject)}</div>` : ''}
    <div style="font-size:14px;line-height:1.75;white-space:pre-wrap;color:#374151">${esc(c.what_to_say.email_body)}</div>
  </div>` : ''}

  ${pushbackCards ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f3">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">When they push back</div>
    ${pushbackCards}
  </div>` : ''}

  ${beyondBase ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f3">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">If base is stuck — negotiate these instead</div>
    ${beyondBase}
  </div>` : ''}

  ${c.competing_offer_advice ? `<div style="background:#f0fdf4;padding:14px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:5px">Competing offer strategy</div>
    <div style="font-size:14px;color:#166534;line-height:1.6">${esc(c.competing_offer_advice)}</div>
  </div>` : ''}

  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f3">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Timing & approach</div>
    <div style="font-size:14px;color:#374151;line-height:1.6">${esc(c.timing_advice)}</div>
  </div>

  ${(c.red_flags||[]).length ? `<div style="background:#fffbeb;padding:14px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:7px">Watch out</div>
    ${(c.red_flags||[]).map(rf=>`<div style="font-size:14px;color:#78350f;padding:4px 0">⚠ ${esc(rf)}</div>`).join('')}
  </div>` : ''}

  <div style="background:#fef2f2;padding:12px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:4px">Don't do this</div>
    <div style="font-size:14px;color:#7f1d1d;line-height:1.6">${esc(c.one_thing_not_to_do)}</div>
  </div>

  <div style="background:#1c1917;color:#57534e;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Salary Negotiation Coach · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, jobTitle: m.jobTitle, offerAmount: m.offerAmount, counterAmount: nr?.counter_amount || null, currency: cur, coaching: c } }];
